const loginPage=$('#loginPage'),application=$('#application');
const loginLanguage=$('#loginLanguage');loginLanguage.value=$('#language').value;
loginLanguage.onchange=()=>{$('#language').value=loginLanguage.value;setLanguage()};
const marketLanguageChange=$('#language').onchange;$('#language').onchange=()=>{marketLanguageChange();loginLanguage.value=$('#language').value};
let registering=false;
function authMode(){syncRegistrationRole();registering=!registering;$('#registrationFields').hidden=!registering;$('#loginName').required=registering;$('#loginPassword').autocomplete=registering?'new-password':'current-password';$('#loginSubmit').textContent=registering?'Create account →':'Log in →';$('#toggleAuth').textContent=registering?'Already registered? Log in':'New here? Create an account';$('#authError').textContent='';translateUI()}
$('#toggleAuth').onclick=authMode;
function syncRegistrationRole(){const hidden=$('#loginRole').value!=='wholesaler';$('#supplierAccountField').hidden=hidden;$('#supplierAccountNote').hidden=hidden;$('#loginSupplier').disabled=hidden}
$('#loginRole').onchange=syncRegistrationRole;syncRegistrationRole();
async function enterAccount(user){currentUser=user;await Promise.all([refreshMarket(),refreshOrders()]);$('#profileName').textContent=user.name;$('#profileInitials').textContent=user.name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();$('#profileRole').textContent=user.role==='vendor'?'Street vendor · Pune':'Wholesaler';document.querySelector('[data-page="supplier"]').hidden=user.role!=='wholesaler';loginPage.hidden=true;application.hidden=false;document.querySelector(`[data-page="${user.role==='wholesaler'?'supplier':'market'}"]`).click();translateUI();$('#logout').focus();window.scrollTo(0,0)}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=$('#loginSubmit');button.disabled=true;$('#authError').textContent='';try{const payload={email:$('#loginEmail').value.trim(),password:$('#loginPassword').value};if(registering)Object.assign(payload,{name:$('#loginName').value.trim(),role:$('#loginRole').value,supplier:$('#loginSupplier').value});const result=await api(registering?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(payload)});$('#loginPassword').value='';await enterAccount(result.user)}catch(error){$('#authError').textContent=error.message;translateUI()}finally{button.disabled=false}};
$('#logout').onclick=async()=>{const button=$('#logout');button.disabled=true;try{await api('/auth/logout',{method:'POST',body:'{}'});if(recognition)recognition.stop();$('#orderDialog').close();currentUser=null;orders=[];renderOrders();application.hidden=true;loginPage.hidden=false;$('#loginForm').reset();syncRegistrationRole();loginLanguage.value=$('#language').value;$('#authError').textContent='';$('#loginEmail').focus();window.scrollTo(0,0)}catch(error){toast(error.message)}finally{button.disabled=false}};
(async()=>{try{const {user}=await api('/auth/me');await enterAccount(user)}catch(error){if(error.status!==401){$('#authError').textContent=error.message;translateUI()}}})();
